module RAM(
    input clk,
    input rst_n,
    input write_en,
    input [$clog2(8)-1:0] write_addr,
    input [5:0] write_data,
    input read_en,
    input [$clog2(8)-1:0] read_addr,
    output reg [5:0] read_data
);
    parameter WIDTH = 6;
    parameter DEPTH = 8;

    reg [WIDTH - 1 : 0] internal_RAM [DEPTH-1:0];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            internal_RAM <= '{default: 6'b0};
            read_data <= 6'b0;
        end else begin
            if (write_en)
                internal_RAM[write_addr] <= write_data;
            if (read_en)
                read_data <= internal_RAM[read_addr];
            else
                read_data <= 6'b0;
        end
    end
endmodule
